public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    if (nums == null) {
        return res;
    }
    int n = nums.length;
    if (n == 0) {
        res.add(new ArrayList<>());
        return res;
    }
    int[] arr = nums.clone();
    while (true) {
        List<Integer> curr = new ArrayList<>(n);
        for (int v : arr) {
            curr.add(v);
        }
        res.add(curr);
        // Compute next permutation
        int i = n - 1;
        while (i > 0 && arr[i - 1] >= arr[i]) {
            i--;
        }
        if (i <= 0) {
            break; // last permutation reached
        }
        int j = n - 1;
        while (arr[j] <= arr[i - 1]) {
            j--;
        }
        // Swap pivot with successor
        int tmp = arr[i - 1];
        arr[i - 1] = arr[j];
        arr[j] = tmp;
        // Reverse suffix
        int left = i;
        int right = n - 1;
        while (left < right) {
            tmp = arr[left];
            arr[left] = arr[right];
            arr[right] = tmp;
            left++;
            right--;
        }
    }
    return res;
}

