public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Find the shortest string to minimize substring enumeration
    String base = strings.get(0);
    for (String s : strings) {
        if (s != null && s.length() < base.length()) {
            base = s;
        }
    }
    if (base == null || base.isEmpty()) {
        return 0;
    }

    int baseLen = base.length();
    // Try lengths from longest to shortest
    for (int len = baseLen; len >= 1; len--) {
        // For each possible starting position within base
        for (int start = 0; start <= baseLen - len; start++) {
            String cand = base.substring(start, start + len);
            String rev = new StringBuilder(cand).reverse().toString();

            boolean ok = true;
            // Check every other string
            for (String t : strings) {
                if (t == null) {
                    ok = false;
                    break;
                }
                // If neither candidate nor its reverse is a substring, fail
                if (!t.contains(cand) && !t.contains(rev)) {
                    ok = false;
                    break;
                }
            }

            if (ok) {
                return len; // Found the largest possible length
            }
        }
    }
    return 0;
}

public int findLargestSubstring(java.util.List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // If any string is null or empty, no common substring exists
    for (String s : strings) {
        if (s == null || s.isEmpty()) {
            return 0;
        }
    }
    // Find the minimum string length to limit search
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        minLen = Math.min(minLen, s.length());
    }
    // Choose the first string as reference for candidate substrings
    String base = strings.get(0);
    for (int len = minLen; len >= 1; len--) {
        java.util.HashSet<String> candidates = new java.util.HashSet<>();
        for (int i = 0; i <= base.length() - len; i++) {
            candidates.add(base.substring(i, i + len));
        }
        for (String cand : candidates) {
            String rev = new StringBuilder(cand).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (!(s.contains(cand) || s.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    int maxLen = 0;
    // Precompute reversed strings to avoid repeated reversing
    List<String> reversed = new ArrayList<>(strings.size());
    for (String s : strings) {
        if (s == null) {
            reversed.add(null);
        } else {
            reversed.add(new StringBuilder(s).reverse().toString());
        }
    }
    int n = strings.size();
    for (int i = 0; i < n; i++) {
        String a = strings.get(i);
        if (a == null) continue;
        for (int j = i + 1; j < n; j++) {
            String b = strings.get(j);
            if (b == null) continue;
            // Compare a with b
            maxLen = Math.max(maxLen, longestCommonSubstringLength(a, b));
            // Compare a with reverse of b
            maxLen = Math.max(maxLen, longestCommonSubstringLength(a, reversed.get(j)));
        }
    }
    return maxLen;
}

private int longestCommonSubstringLength(String s1, String s2) {
    int m = s1.length();
    int n = s2.length();
    int[][] dp = new int[m + 1][n + 1];
    int best = 0;
    for (int i = 1; i <= m; i++) {
        char c1 = s1.charAt(i - 1);
        for (int j = 1; j <= n; j++) {
            if (c1 == s2.charAt(j - 1)) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
                if (dp[i][j] > best) {
                    best = dp[i][j];
                }
            } else {
                dp[i][j] = 0;
            }
        }
    }
    return best;
}

