        // Consider substrings of the first string
        for (int i = 0; i + len <= firstLen; i++) {
            String sub = first.substring(i, i + len);
            // Test the substring itself
            if (!tested.contains(sub)) {
                tested.add(sub);
                if (isCommonAcrossAll(sub, len, strings)) {
                    return len;
