            // Test its reverse as a potential X
            String rev = new StringBuilder(sub).reverse().toString();
            if (!tested.contains(rev)) {
                tested.add(rev);
                if (isCommonAcrossAll(rev, len, strings)) {
                    return len;
                }
            }
        }
    }
    return 0;
}

/**
 * Checks if the candidate string appears (either directly or by inversion)
 * in every string in the list.
 */
private boolean isCommonAcrossAll(String candidate, int len, List<String> strings) {
    for (String s : strings) {
        if (!(s.contains(candidate) || s.contains(new StringBuilder(candidate).reverse().toString()))) {
            return false;
        }
    }
    return true;
}

