private static void dfs(char[][] grid, boolean[][] visited, int[][] dirs,
                        int r, int c, int rows, int cols) {
    visited[r][c] = true;
    for (int[] d : dirs) {
        int nr = r + d[0];
        int nc = c + d[1];
        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                && !visited[nr][nc] && grid[nr][nc] == '@') {
            dfs(grid, visited, dirs, nr, nc, rows, cols);
        }
    }
}

