                deposits++;
                // Depth‑first search to mark all connected '@' cells
                Deque<int[]> stack = new ArrayDeque<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] cell = stack.pop();
                    int cr = cell[0];
                    int cc = cell[1];
                    for (int k = 0; k < 8; k++) {
                        int nr = cr + dr[k];
                        int nc = cc + dc[k];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                            grid[nr][nc] == '@' && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            stack.push(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }
    return deposits;
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles must be non-negative");
    }
    long n = N;
    long regions = 3L * n * (n - 1) + 2;
    if (regions > Integer.MAX_VALUE) {
        throw new ArithmeticException("Result exceeds int range");
    }
    return (int) regions;
}

public static int maxRegions(int N) {
    if (N <= 0) {
        // No triangles mean the plane is a single region
        return 1;
    }
    long regions = 3L * N * N - 3L * N + 2;
    if (regions > Integer.MAX_VALUE) {
        throw new ArithmeticException("Result exceeds 32-bit integer range");
    }
    return (int) regions;
}

