public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate inputs
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }
    if (start.length == 0 || end.length == 0) {
        return "cannot be travelled";
    }
    // Use only the first element when start/end are single‑int arrays (node indices)
    int startNode = start[0];
    int endNode = end[0];

    // Basic bounds check
    if (startNode < 0 || startNode >= n || endNode < 0 || endNode >= n) {
        return "cannot be travelled";
    }

    // Build adjacency list
    List<List<Integer>> adjacency = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        adjacency.add(new ArrayList<>());
    }
    for (int[] edge : paths) {
        if (edge == null || edge.length < 2) {
            continue; // ignore malformed edge
        }
        int u = edge[0];
        int v = edge[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            continue; // skip out of bounds edges
        }
        adjacency.get(u).add(v);
        adjacency.get(v).add(u); // assuming undirected graph; comment out if directed
    }

    // BFS to check reachability
    boolean[] visited = new boolean[n];
    Queue<Integer> queue = new ArrayDeque<>();
    queue.offer(startNode);
    visited[startNode] = true;

    while (!queue.isEmpty()) {
        int curr = queue.poll();
        if (curr == endNode) {
            return "can be travelled";
        }
        for (int neighbour : adjacency.get(curr)) {
            if (!visited[neighbour]) {
                visited[neighbour] = true;
                queue.offer(neighbour);
            }
        }
    }
    return "cannot be travelled";
}

