    if (start.length != n || end.length != n) {
        throw new IllegalArgumentException("Start or end coordinates size mismatch");
    }

    Map<String, List<int[]>> graph = new HashMap<>();
    for (int[] p : paths) {
        if (p == null || p.length != 2 * n) {
            throw new IllegalArgumentException("Invalid path length");
        }
        int[] a = Arrays.copyOfRange(p, 0, n);
        int[] b = Arrays.copyOfRange(p, n, 2 * n);
        graph.computeIfAbsent(Arrays.toString(a), k -> new ArrayList<>()).add(b);
        graph.computeIfAbsent(Arrays.toString(b), k -> new ArrayList<>()).add(a);
    }

    if (Arrays.equals(start, end)) {
        return "can be travelled";
    }

    Set<String> visited = new HashSet<>();
    Queue<int[]> queue = new ArrayDeque<>();
    queue.offer(start);
    visited.add(Arrays.toString(start));

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        String key = Arrays.toString(current);
        List<int[]> neighbors = graph.getOrDefault(key, Collections.emptyList());
        for (int[] nb : neighbors) {
            String nbKey = Arrays.toString(nb);
            if (!visited.contains(nbKey)) {
                if (Arrays.equals(nb, end)) {
                    return "can be travelled";
