    graph.putIfAbsent(endKey, new java.util.ArrayList<>());

    if (paths != null) {
        for (int[] p : paths) {
            if (p == null) {
                continue;
            }
            String keyA;
            String keyB;
            if (p.length == 2 * d) {
                int[] a = new int[d];
                int[] b = new int[d];
                System.arraycopy(p, 0, a, 0, d);
                System.arraycopy(p, d, b, 0, d);
                keyA = java.util.Arrays.toString(a);
                keyB = java.util.Arrays.toString(b);
            } else if (p.length == 2) {
                int[] a = new int[]{p[0]};
                int[] b = new int[]{p[1]};
                keyA = java.util.Arrays.toString(a);
                keyB = java.util.Arrays.toString(b);
            } else {
                // Indeterminate format; skip this path
                continue;
