public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int m = (int) Math.floor(n * 0.05);
    if (m * 2 >= n) {
        return 0.0; // not enough elements to compute mean
    }
    java.util.Arrays.sort(arr);
    long sum = 0;
    for (int i = m; i < n - m; i++) {
        sum += arr[i];
    }
    int count = n - 2 * m;
    return sum / (double) count;
}

