        return null;
    }
    java.util.TreeMap<Character, Integer> map = new java.util.TreeMap<>();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        map.merge(c, 1, Integer::sum);
    }
    StringBuilder result = new StringBuilder(s.length());
    while (!map.isEmpty()) {
        // Ascending part
        java.util.Map.Entry<Character, Integer> entry = map.firstEntry();
        char ascChar = entry.getKey();
        result.append(ascChar);
        int cnt = entry.getValue();
        if (cnt == 1) {
            map.remove(ascChar);
        } else {
            map.put(ascChar, cnt - 1);
        }
        char lastAsc = ascChar;
        while (true) {
            java.util.Map.Entry<Character, Integer> next = map.higherEntry(lastAsc);
            if (next == null) {
                break;
            }
            char nextChar = next.getKey();
            result.append(nextChar);
            int ncnt = next.getValue();
            if (ncnt == 1) {
                map.remove(nextChar);
            } else {
                map.put(nextChar, ncnt - 1);
            }
            lastAsc = nextChar;
        }

        // Descending part
        if (map.isEmpty()) {
            break;
        }
        entry = map.lastEntry();
        char descChar = entry.getKey();
        result.append(descChar);
        int dcnt = entry.getValue();
        if (dcnt == 1) {
            map.remove(descChar);
        } else {
