    }

    // Check possible subset sizes
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) {
            continue;
        }
        long target = (totalSum * k) / n;
        int minC1 = Math.max(0, k - m2);
        int maxC1 = Math.min(k, m1);
        for (int c1 = minC1; c1 <= maxC1; c1++) {
            java.util.Set<Long> set1 = leftSums.get(c1);
            java.util.Set<Long> set2 = rightSums.get(k - c1);
            if (set1 == null || set2 == null) {
                continue;
            }
            for (Long sum1 : set1) {
                long need = target - sum1;
                if (set2.contains(need)) {
                    return true;
                }
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    // Try all possible subset sizes from 1 to n/2
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) {
            continue; // average cannot be integer for this subset size
        }
        int targetSum = (totalSum * k) / n;
        if (canFindSubset(nums, k, targetSum)) {
            return true;
        }
    }
    return false;
}

/**
 * Checks whether there exists a subset of size {@code k} whose elements sum to {@code targetSum}.
 */
private boolean canFindSubset(int[] nums, int k, int targetSum) {
    int n = nums.length;
    // dp[count][sum] indicates whether a sum is achievable with 'count' elements
    boolean[][] dp = new boolean[k + 1][targetSum + 1];
    dp[0][0] = true;

    for (int num : nums) {
        // Traverse counts downward to avoid reuse of the same element
        for (int count = Math.min(k, n); count >= 1; count--) {
            for (int sum = targetSum; sum >= num; sum--) {
                if (dp[count - 1][sum - num]) {
                    dp[count][sum] = true;
                }
            }
        }
    }
    return dp[k][targetSum];
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    @SuppressWarnings("unchecked")
    java.util.List<java.util.Set<Integer>> dp = new java.util.ArrayList<>(n + 1);
    for (int i = 0; i <= n; i++) {
        dp.add(new java.util.HashSet<>());
    }
    dp.get(0).add(0);

    for (int num : nums) {
        for (int k = n - 1; k >= 1; k--) {
            if (dp.get(k - 1).isEmpty()) {
                continue;
            }
            for (int prevSum : dp.get(k - 1)) {
                dp.get(k).add(prevSum + num);
            }
        }
    }

    for (int k = 1; k < n; k++) {
        if ((k * totalSum) % n != 0) {
            continue;
        }
        int target = (k * totalSum) / n;
        if (dp.get(k).contains(target)) {
            return true;
        }
    }
    return false;
}

