    }
    long totalSum = 0;
    for (int v : nums) {
        totalSum += v;
    }

    // dp[k] contains all possible sums of subsets of size k
    @SuppressWarnings("unchecked")
    Set<Long>[] dp = new HashSet[n + 1];
    dp[0] = new HashSet<>();
    dp[0].add(0L);

    for (int num : nums) {
        for (int k = n - 1; k >= 1; k--) {
            if (dp[k - 1] == null) {
                continue;
            }
            if (dp[k] == null) {
                dp[k] = new HashSet<>();
            }
            for (Long prevSum : dp[k - 1]) {
                dp[k].add(prevSum + num);
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n == 0) {
            long target = totalSum * k / n;
            if (dp[k] != null && dp[k].contains(target)) {
                return true;
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // Try subset sizes from 1 to n/2 (checking one side is enough)
    for (int k = 1; k <= n / 2; k++) {
        long product = (long) totalSum * k;
        if (product % n != 0) continue; // target sum not integer
        int target = (int) (product / n);
        // DP: sumsPerSize[s] holds all achievable sums using s elements
        @SuppressWarnings("unchecked")
        java.util.Set<Integer>[] sumsPerSize = new java.util.HashSet[n + 1];
        for (int i = 0; i <= n; i++) {
            sumsPerSize[i] = new java.util.HashSet<>();
        }
        sumsPerSize[0].add(0);
        for (int num : nums) {
            // iterate backwards to avoid using the same element twice
            for (int s = n - 1; s >= 0; s--) {
                java.util.Set<Integer> prevSet = sumsPerSize[s];
                if (prevSet.isEmpty()) continue;
                java.util.Set<Integer> currentSet = sumsPerSize[s + 1];
                for (int sum : prevSet) {
                    currentSet.add(sum + num);
                }
            }
        }
        if (sumsPerSize[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) return 0;
    int n = cost.length;
    if (n == 1) return Math.min(cost[0], 0);
    int prevPrev = 0; // dp[0]
    int prev = 0;     // dp[1]
    int current = 0;
    for (int i = 2; i <= n; i++) {
        int costPrev = (i - 1 < n) ? cost[i - 1] + prev : Integer.MAX_VALUE;
        int costPrevPrev = (i - 2 < n) ? cost[i - 2] + prevPrev : Integer.MAX_VALUE;
        current = Math.min(costPrev, costPrevPrev);
        prevPrev = prev;
        prev = current;
    }
    return current;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    // dpPrevPrev represents dp[i-2], dpPrev represents dp[i-1]
    int dpPrevPrev = 0; // cost to reach step 0 (starting point, no cost)
    int dpPrev = 0;     // cost to reach step 1 (starting point, no cost)

    for (int i = 2; i <= n; i++) {
        int costIfStepFromPrev = dpPrev + cost[i - 1];
        int costIfStepFromPrevPrev = dpPrevPrev + cost[i - 2];
        int dpCurr = Math.min(costIfStepFromPrev, costIfStepFromPrevPrev);
        dpPrevPrev = dpPrev;
        dpPrev = dpCurr;
    }
    return dpPrev;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }
    if (n == 2) {
        return Math.min(cost[0], cost[1]);
    }
    int prev2 = cost[0];
    int prev1 = cost[1];
    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = current;
    }
    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // If there is only one step, you can start at the next step (index 1) and pay nothing.
        return 0;
    }
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int curr = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

