public boolean hasAllCodes(String s, int k) {
    if (k <= 0) return true;
    int n = s.length();
    if (n < k) return false;

    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int count = 0;
    int mask = total - 1;
    int code = 0;

    for (int i = 0; i < n; i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[code]) {
                seen[code] = true;
                count++;
                if (count == total) {
                    return true;
                }
            }
        }
    }
    return false;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    if (n < k) {
        return false;
    }
    if (k >= 31) { // 1 << k would overflow and array would be too large
        return false;
    }
    int total = 1 << k;          // total number of possible binary strings of length k
    boolean[] seen = new boolean[total];
    int mask = 0;
    int seenCount = 0;
    int allOnMask = total - 1;

    for (int i = 0; i < n; i++) {
        // Build the next k-bit mask
        mask = ((mask << 1) & allOnMask) | (s.charAt(i) - '0');
        if (i >= k - 1) { // window of size k is ready
            if (!seen[mask]) {
                seen[mask] = true;
                seenCount++;
                if (seenCount == total) {
                    return true; // all possible codes found
                }
            }
        }
    }
    return false; // not all codes appeared
}

public boolean hasAllCodes(String s, int k) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (k <= 0) {
        return true; // vacuously true for non‑positive k
    }
    int n = s.length();
    if (n < k) {
        return false;
    }

    // Decide whether to use a boolean array or a HashSet
    // Use array when 2^k is reasonable; otherwise fallback to HashSet
    long possibleCodes = 1L << k; // avoid overflow for k > 30
    if (k > 20 || possibleCodes > 1_000_000L) {
        // Use HashSet for large k
        java.util.Set<Integer> seen = new java.util.HashSet<>();
        int code = 0;
        for (int i = 0; i < k; i++) {
            code = (code << 1) | (s.charAt(i) - '0');
        }
        seen.add(code);
        int mask = (1 << k) - 1;
        for (int i = k; i < n; i++) {
            code = ((code << 1) & mask) | (s.charAt(i) - '0');
            seen.add(code);
        }
        return seen.size() == possibleCodes;
    } else {
        boolean[] seen = new boolean[(int) possibleCodes];
        int code = 0;
        for (int i = 0; i < k; i++) {
            code = (code << 1) | (s.charAt(i) - '0');
        }
        seen[code] = true;
        int mask = (1 << k) - 1;
        for (int i = k; i < n; i++) {
            code = ((code << 1) & mask) | (s.charAt(i) - '0');
            seen[code] = true;
        }
        for (boolean present : seen) {
            if (!present) return false;
        }
        return true;
    }
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0 || s.length() < k) {
        return false;
    }
    int totalCodes = 1 << k;
    boolean[] seen = new boolean[totalCodes];
    int seenCount = 0;
    int mask = totalCodes - 1;
    int code = 0;
    for (int i = 0; i < s.length(); i++) {
        code = ((code << 1) + (s.charAt(i) - '0')) & mask;
        if (i >= k - 1) {
            if (!seen[code]) {
                seen[code] = true;
                seenCount++;
                if (seenCount == totalCodes) {
                    return true;
                }
            }
        }
    }
    return false;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    if (n < k) {
        return false;
    }
    int total = 1 << k; // Number of binary strings of length k
    // If not enough substrings to cover all possibilities, it's impossible
    if (total > n - k + 1) {
        return false;
    }
    boolean[] seen = new boolean[total];
    int mask = total - 1; // Mask to keep only k bits
    int code = 0;
    // Build the code for the first window of size k
    for (int i = 0; i < k; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }
    seen[code] = true;
    int seenCount = 1;
    // Slide the window through the rest of the string
    for (int i = k; i < n; i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[code]) {
            seen[code] = true;
            seenCount++;
            if (seenCount == total) {
                return true; // All codes found
            }
        }
    }
    return seenCount == total;
}

public int isPrefixOfWord(String sentence, String searchWord) {
