public int minInsertions(String s) {
    if (s == null) {
        return 0;
    }
    int insertions = 0;
    int unmatchedOpen = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            unmatchedOpen++;
        } else if (c == ')') {
            if (unmatchedOpen > 0) {
                unmatchedOpen--;
            } else {
                // Need an opening parenthesis before this ')'
                insertions++;
            }
        }
    }
    // Remaining unmatched '(' need ')' to balance each
    insertions += unmatchedOpen;
    return insertions;
}

public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int balance = 0;
    int insertions = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            balance--;
        } else {
            // If unexpected characters appear, ignore them.
            continue;
        }
        if (balance < 0) {
            insertions++;
            balance = 0;
        }
    }
    return insertions + balance;
}

public int minInsertions(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    int result = 0;   // Count of insertions needed
    int balance = 0;  // Number of unmatched '('
    for (int i = 0; i < s.length(); i++) {
        char ch = s.charAt(i);
        if (ch != '(' && ch != ')') {
            throw new IllegalArgumentException("String can only contain '(' or ')'");
        }
        if (ch == '(') {
            balance++;
        } else { // ch == ')'
            if (balance > 0) {
                balance--;
            } else {
                // We need an inserted '(' before this ')'
                result++;
            }
        }
    }
    // Any remaining unmatched '(' need ')' insertions
    result += balance;
    return result;
}

