public int minOperations(int n) {
    if (n <= 1) {
        return 0;
    }
    long operations = 0L;
    for (int i = 0; i < n; i++) {
        int val = 2 * i + 1;
        if (val > n) {
            operations += val - n;
        }
    }
    if (operations > Integer.MAX_VALUE) {
        throw new ArithmeticException("Result exceeds integer range");
    }
    return (int) operations;
}

public int minOperations(int n) {
    if (n <= 0) return 0;
    long half = n / 2L;
    long result = (n % 2 == 0) ? half * half : half * (half + 1L);
    return (int) result;
}

public int minOperations(int n) {
    if (n <= 1) return 0;
    int lb = (n + 1) / 2;          // lower bound where arr[i] > target
    int count = n - lb;            // number of indices with excess
    return lb * count;             // total units to transfer equals minimal operations
}

public int minOperations(int n) {
    if (n <= 0) {
        return 0;
    }
    int floorHalf = n / 2;          // ⌊n/2⌋
    int ceilHalf = (n + 1) / 2;     // ⌈n/2⌉
    long ops = (long) floorHalf * ceilHalf;
    return (int) ops;
}

