    }

    int currentMax = 0, maxSum = Integer.MIN_VALUE;
    for (int val : nums) {
        currentMax = Math.max(currentMax + val, 0);
        if (currentMax > maxSum) {
            maxSum = currentMax;
        }
    }

    int currentMin = 0, minSum = Integer.MAX_VALUE;
    for (int val : nums) {
        currentMin = Math.min(currentMin + val, 0);
        if (currentMin < minSum) {
            minSum = currentMin;
        }
    }

