}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer");
    }
    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int next = fibs.get(fibs.size() - 1) + fibs.get(fibs.size() - 2);
        if (next > k) {
            break;
        }
        fibs.add(next);
    }
    // Greedy approach: subtract the largest Fibonacci number repeatedly
    int count = 0;
    int remaining = k;
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int fib = fibs.get(i);
        while (remaining >= fib) {
            remaining -= fib;
            count++;
        }
    }
    return count;
}

