    if (k <= 0) {
        throw new IllegalArgumentException("k must be positive");
    }

    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(2);
    while (true) {
        int size = fibs.size();
        int next = fibs.get(size - 1) + fibs.get(size - 2);
        if (next > k) {
            break;
        }
        fibs.add(next);
    }

    int count = 0;
    int idx = fibs.size() - 1;
    while (k > 0) {
        if (fibs.get(idx) <= k) {
            k -= fibs.get(idx);
            count++;
        } else {
            idx--;
        }
    }
    return count;
}

