public int kthFactor(int n, int k) {
    // Validate input
    if (n <= 0 || k <= 0) {
        return -1;
    }

    java.util.List<Integer> factors = new java.util.ArrayList<>();

    // Find all divisors
    for (int i = 1; (long) i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            int complement = n / i;
            if (complement != i) {
                factors.add(complement);
            }
        }
    }

    // Sort in ascending order
    java.util.Collections.sort(factors);

    // Return kth factor or -1 if not enough factors
    if (k > factors.size()) {
        return -1;
    }
    return factors.get(k - 1);
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();

    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }

    int count = 0;

    // Check small factors (already ascending)
    for (int val : small) {
        count++;
        if (count == k) {
            return val;
        }
    }

    // Check large factors in ascending order by iterating reverse of large list
    for (int idx = large.size() - 1; idx >= 0; idx--) {
        count++;
        if (count == k) {
            return large.get(idx);
        }
    }

    return -1; // Less than k factors
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int pair = n / i;
            if (pair != i) {
                large.add(pair);
            }
        }
    }
    java.util.Collections.reverse(large);
    int total = small.size() + large.size();
    if (k > total) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        return large.get(k - small.size() - 1);
    }
}

