        return s;
    }
    StringBuilder stack = new StringBuilder();
    for (char c : s.toCharArray()) {
        int n = stack.length() - 1;
        if (n >= 0) {
            char top = stack.charAt(n);
            // If c and top are same letter but different case (abs diff == 32)
            if (Math.abs(c - top) == 32) {
                stack.deleteCharAt(n);  // remove the pair
                continue;
            }
        }
        stack.append(c);  // keep c
    }
    return stack.toString();
}

public String makeGood(String s) {
    if (s == null || s.isEmpty()) {
        return s == null ? "" : s;
    }
    StringBuilder stack = new StringBuilder(s.length());
    for (char c : s.toCharArray()) {
        stack.append(c);
        int len = stack.length();
        if (len >= 2) {
            char last = stack.charAt(len - 1);
            char prev = stack.charAt(len - 2);
            if (Math.abs(last - prev) == 32) { // one is lower case and the other its upper case
                stack.setLength(len - 2); // remove the bad pair
            }
        }
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) return 0;
    class Solver {
        int max = 0;
        void dfs(int idx, Set<String> used) {
            if (idx == s.length()) {
                max = Math.max(max, used.size());
                return;
            }
            for (int end = idx + 1; end <= s.length(); end++) {
                String sub = s.substring(idx, end);
                if (!used.contains(sub)) {
                    used.add(sub);
                    dfs(end, used);
                    used.remove(sub);
                }
            }
        }
    }
    Solver solver = new Solver();
    solver.dfs(0, new HashSet<>());
    return solver.max;
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int[] max = {0};
    dfs(0, new HashSet<>(), max, s);
    return max[0];
}

private void dfs(int index, Set<String> seen, int[] max, String s) {
    if (index == s.length()) {
        max[0] = Math.max(max[0], seen.size());
        return;
    }
    for (int end = index + 1; end <= s.length(); end++) {
        String part = s.substring(index, end);
        if (seen.contains(part)) {
            continue;
        }
        seen.add(part);
        dfs(end, seen, max, s);
        seen.remove(part);
    }
}

public class MaxUniqueSplit {
    /**
     * Returns the maximum number of unique substrings that can be obtained by splitting the string.
     *
     * @param s the input string consisting of lowercase English letters
     * @return the maximum number of unique substrings, or 0 if the input is null or empty
     */
    public int maxUniqueSplit(String s) {
        if (s == null || s.isEmpty()) {
            return 0;
        }
        int[] max = new int[1];
        dfs(0, new java.util.HashSet<>(), s, max);
        return max[0];
    }

    private void dfs(int pos, java.util.Set<String> used, String s, int[] max) {
        if (pos == s.length()) {
            max[0] = Math.max(max[0], used.size());
            return;
        }
        for (int end = pos + 1; end <= s.length(); end++) {
            String sub = s.substring(pos, end);
            if (used.add(sub)) {
                dfs(end, used, s, max);
                used.remove(sub);
            }
        }
    }
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    return dfs(s, new java.util.HashSet<>());
}

private int dfs(String remaining, java.util.Set<String> used) {
    if (remaining.isEmpty()) {
        return 0;
    }
    int max = 0;
    for (int i = 1; i <= remaining.length(); i++) {
        String prefix = remaining.substring(0, i);
        if (!used.contains(prefix)) {
            used.add(prefix);
            int count = 1 + dfs(remaining.substring(i), used);
            if (count > max) {
                max = count;
            }
            used.remove(prefix);
        }
    }
    return max;
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int[] maxCount = {0};
    Set<String> used = new HashSet<>();
    dfs(s, 0, used, maxCount);
    return maxCount[0];
}

private void dfs(String s, int start, Set<String> used, int[] maxCount) {
    if (start == s.length()) {
        if (used.size() > maxCount[0]) {
            maxCount[0] = used.size();
        }
        return;
    }
    for (int end = start + 1; end <= s.length(); end++) {
        String part = s.substring(start, end);
        if (used.add(part)) {
            dfs(s, end, used, maxCount);
            used.remove(part);
        }
    }
}

