public String getSmallestString(int n, int k) {
    // Edge case handling: if the requested value is outside feasible bounds.
    if (n <= 0) {
        return "";
    }
    int minPossible = n;          // all 'a's
    int maxPossible = n * 26;      // all 'z's
    if (k < minPossible || k > maxPossible) {
        // Not possible to construct such a string; returning empty string as per assumption.
        return "";
    }

    char[] ans = new char[n];
    // Start with all 'a's.
    for (int i = 0; i < n; i++) {
        ans[i] = 'a';
    }

    int remaining = k - minPossible; // amount still needed to distribute.
    // Greedily add to characters from the end (rightmost) to keep the string
    // lexicographically smallest.
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // maximum we can increase from 'a'.
        ans[i] = (char) (ans[i] + add);
        remaining -= add;
    }

    return new String(ans);
}

public String getSmallestString(int n, int k) {
    // Check for impossible cases
    if (n <= 0 || k < n || k > 26 * n) {
        throw new IllegalArgumentException("Invalid input: no string satisfies the constraints.");
    }

    char[] result = new char[n];
    // Initialize all characters to 'a' (value 1)
    java.util.Arrays.fill(result, 'a');

    int remaining = k - n; // amount of value still needed beyond all 'a's

    // Distribute the remaining value starting from the end to keep string lexicographically minimal
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // each character can be increased up to 'z' (value 26)
        result[i] = (char) ('a' + add);
        remaining -= add;
    }

    return new String(result);
}

