    while (i <= n) {
        long high = n / (i * 10);
        int curr = (int) ((n / i) % 10);
        long low = n % i;
        if (curr > 1) {
            count += (high + 1) * i;
        } else if (curr == 1) {
            count += high * i + low + 1;
        } else {
            count += high * i;
        }
        i *= 10;
    }
    return (int) count;
}

