public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) {
        return 1;
    }
    java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
    for (int v : A) {
        freq.put(v, freq.getOrDefault(v, 0) + 1);
    }
    int[] count = new int[]{0};
    for (int key : new java.util.ArrayList<>(freq.keySet())) {
        int newCnt = freq.get(key) - 1;
        if (newCnt == 0) {
            freq.remove(key);
        } else {
            freq.put(key, newCnt);
        }
        backtrack(key, freq, n - 1, count);
        freq.put(key, freq.getOrDefault(key, 0) + 1);
    }
    return count[0];
}

private static void backtrack(int prev, java.util.HashMap<Integer, Integer> freq, int remaining, int[] count) {
    if (remaining == 0) {
        count[0]++;
        return;
    }
    for (int num : new java.util.ArrayList<>(freq.keySet())) {
        if (isSquare(prev + num)) {
            int newCnt = freq.get(num) - 1;
            if (newCnt == 0) {
                freq.remove(num);
            } else {
                freq.put(num, newCnt);
            }
            backtrack(num, freq, remaining - 1, count);
            freq.put(num, freq.getOrDefault(num, 0) + 1);
        }
    }
}

private static boolean isSquare(int x) {
    int r = (int) Math.sqrt(x);
    return r * r == x;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 1;
    java.util.Arrays.sort(A);
    boolean[] used = new boolean[n];
    int[] result = new int[1];

    class Solver {
        void dfs(int depth, int prev) {
            if (depth == n) {
                result[0] += 1;
                return;
            }
            for (int i = 0; i < n; i++) {
                if (used[i]) continue;
                if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) continue;
                if (depth > 0) {
                    int sum = prev + A[i];
                    int root = (int) Math.round(Math.sqrt(sum));
                    if (root * root != sum) continue;
                }
                used[i] = true;
                dfs(depth + 1, A[i]);
                used[i] = false;
            }
        }
    }

    new Solver().dfs(0, 0);
    return result[0];
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) return 0;
    int n = A.length;
    java.util.Arrays.sort(A);
    boolean[] used = new boolean[n];
    int[] count = new int[1];
    java.util.HashSet<Integer> squares = new java.util.HashSet<>();
    for (int i = 0; i <= 2 * 1000; i++) { // sufficient range for sums of non-negative ints
        squares.add(i * i);
    }

    java.util.function.BiConsumer<Integer, Integer> dfs = new java.util.function.BiConsumer<Integer, Integer>() {
        @Override
        public void accept(Integer pos, Integer prev) {
            if (pos == n) {
                count[0]++;
                return;
            }
            for (int i = 0; i < n; i++) {
                if (used[i]) continue;
                if (i > 0 && !used[i - 1] && A[i] == A[i - 1]) continue;
                if (pos > 0 && !squares.contains(prev + A[i])) continue;
                used[i] = true;
                accept(pos + 1, A[i]);
                used[i] = false;
            }
        }
    };
    dfs.accept(0, 0);
    return count[0];
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) return 0;
    int n = A.length;
    // Compute maximum possible sum to identify perfect squares
    int maxVal = 0;
    for (int v : A) if (v > maxVal) maxVal = v;
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    // Build list of unique values and their frequencies
    java.util.Map<Integer, Integer> freqMap = new java.util.HashMap<>();
    for (int v : A) freqMap.put(v, freqMap.getOrDefault(v, 0) + 1);
    java.util.List<Integer> values = new java.util.ArrayList<>(freqMap.keySet());
    java.util.Collections.sort(values);
    int m = values.size();
    int[] freq = new int[m];
    for (int i = 0; i < m; i++) freq[i] = freqMap.get(values.get(i));
    java.util.Map<String, Integer> memo = new java.util.HashMap<>();

    java.util.function.Function<Object, Integer> dfs = new java.util.function.Function<Object, Integer>() {
        @Override
        public Integer apply(Object obj) {
            String key = memoKey(freq, (int) obj);
            if (memo.containsKey(key)) return memo.get(key);
            int remaining = 0;
            for (int c : freq) remaining += c;
            if (remaining == 0) return 1;
            int last = (int) obj;
            int total = 0;
            for (int i = 0; i < m; i++) {
                if (freq[i] == 0) continue;
                int val = values.get(i);
                if (last != -1 && !isSquare[last + val]) continue;
                freq[i]--;
                total += dfs.apply(val);
                freq[i]++; // backtrack
            }
            memo.put(key, total);
            return total;
        }
    };

    String memoKey(int[] freqArr, int last) {
        StringBuilder sb = new StringBuilder();
        sb.append(last).append('#');
        for (int i = 0; i < freqArr.length; i++) {
            sb.append(freqArr[i]).append(',');
        }
        return sb.toString();
    }

    return dfs.apply(-1);
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    java.util.Stack<Integer> stack = new java.util.Stack<>();

    for (int i = 0; i <= heights.length; i++) {
        int currentHeight = (i == heights.length) ? 0 : heights[i];

        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int leftBoundary = stack.isEmpty() ? 0 : stack.peek() + 1;
            int width = i - leftBoundary;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }

        stack.push(i);
    }

    return maxArea;
}

