    return result;
}

private static void backtrack(int idx, int n, int half, char[] arr, List<String> result) {
    if (idx == half) {
        if (n % 2 == 1) {
            char[] midDigits = {'0', '1', '8'};
            for (char mid : midDigits) {
                arr[half] = mid;
                result.add(new String(arr));
            }
        } else {
            result.add(new String(arr));
        }
        return;
    }
    char[] digits = {'0', '1', '8', '6', '9'};
    for (char d : digits) {
        if (idx == 0 && n > 1 && d == '0') {
            continue; // leading zero is not allowed for length > 1
        }
        arr[idx] = d;
        char mapped;
        switch (d) {
            case '0': mapped = '0'; break;
            case '1': mapped = '1'; break;
            case '8': mapped = '8'; break;
            case '6': mapped = '9'; break;
            case '9': mapped = '6'; break;
            default: mapped = '?'; // unreachable
        }
        arr[n - 1 - idx] = mapped;
        backtrack(idx + 1, n, half, arr, result);
    }
}

