}

private static void build(int left, int right, char[] arr, List<String> res) {
    if (left > right) {
        res.add(new String(arr));
        return;
    }
    if (left == right) {
        char[] middle = {'0', '1', '8'};
        for (char c : middle) {
            arr[left] = c;
            res.add(new String(arr));
        }
        return;
    }
    char[] firstDigits = {'0', '1', '6', '8', '9'};
    for (char d : firstDigits) {
        if (left == 0 && arr.length > 1 && d == '0') {
            continue;
        }
        char r = mirror(d);
        arr[left] = d;
        arr[right] = r;
        build(left + 1, right - 1, arr, res);
    }
}

private static char mirror(char c) {
    switch (c) {
        case '0': return '0';
        case '1': return '1';
        case '8': return '8';
        case '6': return '9';
        case '9': return '6';
        default:  return ' ';
    }
}

